```verilog
`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg  [5:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y  (y),
        .w  (w),
        .Y1 (Y1),
        .Y3 (Y3)
    );

    integer errors = 0;
    integer i, j;

    // Task to check outputs against expected values
    task check_outputs(input [5:0] exp_y, input exp_w, input exp_Y1, input exp_Y3);
        begin
            y = exp_y;
            w = exp_w;
            #5; // Wait for combinational propagation

            if ((Y1 !== exp_Y1) || (Y3 !== exp_Y3)) begin
                $display("Mismatch: y=6'b%b, w=%b | Expected Y1=%b, Y3=%b | Got Y1=%b, Y3=%b",
                         exp_y, exp_w, exp_Y1, exp_Y3, Y1, Y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 6'b000000;
        w = 1'b0;
        #10;

        // Test all valid one-hot states with w = 0 and w = 1

        // State A (y[0] = 6'b000001)
        // A --1--> B (Y1=1), A --0--> A (Y1=0, Y3=0)
        check_outputs(6'b000001, 1'b0, 1'b0, 1'b0);
        check_outputs(6'b000001, 1'b1, 1'b1, 1'b0);

        // State B (y[1] = 6'b000010)
        // B --1--> C, B --0--> D (Y3=1)
        check_outputs(6'b000010, 1'b0, 1'b0, 1'b1);
        check_outputs(6'b000010, 1'b1, 1'b0, 1'b0);

        // State C (y[2] = 6'b000100)
        // C --1--> E, C --0--> D (Y3=1)
        check_outputs(6'b000100, 1'b0, 1'b0, 1'b1);
        check_outputs(6'b000100, 1'b1, 1'b0, 1'b0);

        // State D (y[3] = 6'b001000)
        // D --1--> F, D --0--> A
        check_outputs(6'b001000, 1'b0, 1'b0, 1'b0);
        check_outputs(6'b001000, 1'b1, 1'b0, 1'b0);

        // State E (y[4] = 6'b010000)
        // E --1--> E, E --0--> D (Y3=1)
        check_outputs(6'b010000, 1'b0, 1'b0, 1'b1);
        check_outputs(6'b010000, 1'b1, 1'b0, 1'b0);

        // State F (y[5] = 6'b100000)
        // F --1--> C, F --0--> D (Y3=1)
        check_outputs(6'b100000, 1'b0, 1'b0, 1'b1);
        check_outputs(6'b100000, 1'b1, 1'b0, 1'b0);

        // Additional randomized / edge case tests
        // Multiple one-hot or zero/invalid states just to ensure robustness
        check_outputs(6'b000000, 1'b0, 1'b0, 1'b0);
        check_outputs(6'b111111, 1'b1, 1'b1, 1'b0);

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
